def numeroter_proformas_existantes(apps, schema_editor):
    """Donne à chaque proforma existante un numéro unique par année (ordre de
    création), puis règle le compteur pour que la suivante continue la série.
    Sans cela, toutes recevaient (2026, 1) et la contrainte d'unicité échouait.

    Ne fait RIEN si les numéros sont déjà tous différents : on ne renumérote
    jamais des proformas déjà émises."""
    from django.db.models import Count

    OrderPro = apps.get_model("proforma", "OrderPro")
    CompteurFacturePro = apps.get_model("proforma", "CompteurFacturePro")

    doublons = (OrderPro.objects.values("annee", "sequence")
                .annotate(n=Count("pk")).filter(n__gt=1).exists())
    if not doublons:
        return

    derniers = {}
    for order in OrderPro.objects.order_by("created_at", "pk"):
        annee = order.created_at.year
        derniers[annee] = derniers.get(annee, 0) + 1
        OrderPro.objects.filter(pk=order.pk).update(annee=annee, sequence=derniers[annee])

    for annee, dernier in derniers.items():
        CompteurFacturePro.objects.update_or_create(annee=annee, defaults={"dernier": dernier})


